import pandas as pd
raw = pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)

def clean(s):
    return pd.to_numeric(s.str.replace(',', '.', regex=False).str.strip(), errors='coerce')

cols = ['Lactate','Troponin_I','Troponin_T','Free_T4','Free_T3','Serum_Iron','TIBC']
for col in cols:
    v=clean(raw[col])
    if col=='Lactate':
        for thr in [5,10,20]:
            print(col,'>thr',thr,(v>thr).sum())
    elif col in ['Troponin_I','Troponin_T']:
        for thr in [0.1,1,10,100]:
            print(col,'>thr',thr,(v>thr).sum())
    elif col=='Free_T4':
        for thr in [2,5,10]:
            print(col,'>thr',thr,(v>thr).sum())
    elif col=='Free_T3':
        for thr in [5,10]:
            print(col,'>thr',thr,(v>thr).sum())
    elif col in ['Serum_Iron','TIBC']:
        for thr in [30,50,100]:
            print(col,'<thr',thr,(v<thr).sum())
